function session.getWebhookRewards()
    local service = Workspace:FindFirstChild("WorkspaceScriptService")
    local rewards = service and service:FindFirstChild("Rewards")
    if not rewards then
        return "None"
    end

    local parts = {}

    for _, value in ipairs(rewards:GetChildren()) do
        if value:IsA("ValueBase")
            and value.Name ~= "Result"
            and value.Name ~= "BanishmentTimer"
            and value.Name ~= "Coins"
            and value.Name ~= "Exp"
        then
            local number = tonumber(value.Value)
            if number then
                if number ~= 0 then
                    parts[#parts + 1] = value.Name .. ": " .. tostring(number)
                end
            elseif tostring(value.Value) ~= "" then
                parts[#parts + 1] = value.Name .. ": " .. tostring(value.Value)
            end
        end
    end

    table.sort(parts)

    if #parts == 0 then
        return "None"
    end

    local result = table.concat(parts, "\n")
    if #result > 900 then
        result = result:sub(1, 897) .. "..."
    end
    return result
end

function session.getWebhookMatchSeconds()
    -- Authoritative game timer used by the game's own EndFrame scripts.
    local service = Workspace:FindFirstChild("WorkspaceScriptService")
    local totalGameTime = service and service:FindFirstChild("TotalGameTime")

    if totalGameTime and tonumber(totalGameTime.Value) then
        return math.max(0, tonumber(totalGameTime.Value))
    end

    -- Fallback only if this game build does not expose TotalGameTime.
    local endFrame = playerGui:FindFirstChild("EndFrame", true)
    if endFrame then
        local timeObject = endFrame:FindFirstChild("Time", true)
        if timeObject and (timeObject:IsA("TextLabel") or timeObject:IsA("TextButton")) then
            local value = tostring(timeObject.Text or "")

            local h, m, s = value:match("(%d+):(%d+):(%d+)")
            if h and m and s then
                return tonumber(h) * 3600 + tonumber(m) * 60 + tonumber(s)
            end

            local mm, ss = value:match("(%d+):(%d+)")
            if mm and ss then
                return tonumber(mm) * 60 + tonumber(ss)
            end
        end
    end

    return nil
end

function session.getWebhookMatchTime()
    local seconds = session.getWebhookMatchSeconds()
    if not seconds then
        return "Unknown"
    end

    seconds = math.max(0, math.floor(seconds + 0.5))
    local hours = math.floor(seconds / 3600)
    local minutes = math.floor(seconds / 60) % 60
    local secs = seconds % 60

    if hours > 0 then
        return string.format("%d:%02d:%02d", hours, minutes, secs)
    end

    return string.format("%02d:%02d", minutes, secs)
end

function session.formatWebhookNumber(value)
    value = tonumber(value)
    if not value then
        return "N/A"
    end

    value = math.floor(value + 0.5)

    local sign = value < 0 and "-" or ""
    local digits = tostring(math.abs(value))
    local formatted = digits

    while true do
        local nextValue, count = formatted:gsub("^(%d+)(%d%d%d)", "%1,%2")
        formatted = nextValue
        if count == 0 then
            break
        end
    end

    return sign .. formatted
end

function session.getWebhookFarmStats()
    local service = Workspace:FindFirstChild("WorkspaceScriptService")
    local rewards = service and service:FindFirstChild("Rewards")

    local coins = 0
    local exp = 0

    if rewards then
        local coinsValue = rewards:FindFirstChild("Coins")
        local expValue = rewards:FindFirstChild("Exp")

        coins = coinsValue and tonumber(coinsValue.Value) or 0
        exp = expValue and tonumber(expValue.Value) or 0
    end

    local seconds = session.getWebhookMatchSeconds()
    local coinsPerHour
    local expPerHour

    if seconds and seconds > 0 then
        coinsPerHour = coins * 3600 / seconds
        expPerHour = exp * 3600 / seconds
    end

    return {
        coins = coins,
        exp = exp,
        seconds = seconds,
        coinsPerHour = coinsPerHour,
        expPerHour = expPerHour,
    }
end

function session.accountWebhookRun(result)
    local farm = session.getWebhookFarmStats()
    local summary = session.farmSession

    summary.runs = (tonumber(summary.runs) or 0) + 1
    if result == "Triumph" then
        summary.wins = (tonumber(summary.wins) or 0) + 1
    elseif result == "Defeat" then
        summary.losses = (tonumber(summary.losses) or 0) + 1
    end

    summary.coins = (tonumber(summary.coins) or 0) + (tonumber(farm.coins) or 0)
    summary.exp = (tonumber(summary.exp) or 0) + (tonumber(farm.exp) or 0)
    summary.totalGameSeconds = (tonumber(summary.totalGameSeconds) or 0)
        + (tonumber(farm.seconds) or 0)

    return summary
end

function session.getWebhookSessionStats()
    local summary = session.farmSession
    local startedAt = tonumber(summary.startedAt) or os.time()
    local totalGameSeconds = tonumber(summary.totalGameSeconds) or 0
    local runtime = math.max(1, os.time() - startedAt, totalGameSeconds)
    local runs = tonumber(summary.runs) or 0
    local wins = tonumber(summary.wins) or 0
    local losses = tonumber(summary.losses) or 0
    local coins = tonumber(summary.coins) or 0
    local exp = tonumber(summary.exp) or 0

    return {
        runs = runs,
        wins = wins,
        losses = losses,
        coins = coins,
        exp = exp,
        runtime = runtime,
        winRate = runs > 0 and (wins / runs * 100) or 0,
        avgRunSeconds = runs > 0 and (totalGameSeconds / runs) or 0,
        coinsPerHour = coins * 3600 / runtime,
        expPerHour = exp * 3600 / runtime,
    }
end

function session.formatWebhookDuration(seconds)
    seconds = math.max(0, math.floor(tonumber(seconds) or 0))
    local hours = math.floor(seconds / 3600)
    local minutes = math.floor(seconds / 60) % 60
    local secs = seconds % 60

    if hours > 0 then
        return string.format("%dh %02dm %02ds", hours, minutes, secs)
    end

    return string.format("%dm %02ds", minutes, secs)
end

function session.sendWebhook(result, isTest)
    if session.webhook.busy then
        return false, "busy"
    end

    local url = Options.CTDIGWebhookURL and tostring(Options.CTDIGWebhookURL.Value or "") or ""
    url = url:gsub("^%s+", ""):gsub("%s+$", "")

    if url == "" then
        session.setWebhookStatus("Webhook: URL is empty")
        return false, "URL is empty"
    end

    if not url:match("^https://[%w%.%-]+/api/webhooks/") then
        session.setWebhookStatus("Webhook: invalid Discord webhook URL")
        return false, "invalid Discord webhook URL"
    end

    local requestFn = session.getWebhookRequest()
    if not requestFn then
        session.setWebhookStatus("Webhook: executor request() unavailable")
        return false, "request() unavailable"
    end

    session.webhook.busy = true
    session.setWebhookStatus(isTest and "Webhook: sending test..." or "Webhook: sending result...")

    local cleanResult = tostring(result or "Unknown")
    local title
    local color

    if isTest then
        title = "CTDIG Webhook Test"
        color = 5793266
    elseif cleanResult == "Triumph" then
        title = "✅ Triumph"
        color = 5763719
    else
        title = "❌ Defeat"
        color = 15548997
    end

    local fields = {
        {
            name = "Player",
            value = tostring(player.Name),
            inline = true,
        },
        {
            name = "Map",
            value = tostring(getMapName()),
            inline = true,
        },
        {
            name = "Wave",
            value = tostring(getWave()),
            inline = true,
        },
        {
            name = "Time",
            value = tostring(session.getWebhookMatchTime()),
            inline = true,
        },
        {
            name = "Macro",
            value = "ctdig.lua",
            inline = true,
        },
    }

    if not isTest then
        local farm = session.getWebhookFarmStats()

        fields[#fields + 1] = {
            name = "🪙 Coins Earned",
            value = session.formatWebhookNumber(farm.coins),
            inline = true,
        }

        fields[#fields + 1] = {
            name = "🪙 Coins / Hour",
            value = farm.coinsPerHour
                and ("≈ " .. session.formatWebhookNumber(farm.coinsPerHour) .. "/h")
                or "N/A",
            inline = true,
        }

        fields[#fields + 1] = {
            name = "⭐ EXP Earned",
            value = session.formatWebhookNumber(farm.exp),
            inline = true,
        }

        fields[#fields + 1] = {
            name = "⭐ EXP / Hour",
            value = farm.expPerHour
                and ("≈ " .. session.formatWebhookNumber(farm.expPerHour) .. "/h")
                or "N/A",
            inline = true,
        }

        local summary = session.getWebhookSessionStats()
        fields[#fields + 1] = {
            name = "📊 Session",
            value = string.format(
                "Run #%d\nWins: %d | Losses: %d\nWin rate: %.1f%%",
                summary.runs,
                summary.wins,
                summary.losses,
                summary.winRate
            ),
            inline = false,
        }
        fields[#fields + 1] = {
            name = "🪙 Session Coins",
            value = session.formatWebhookNumber(summary.coins)
                .. "\n≈ "
                .. session.formatWebhookNumber(summary.coinsPerHour)
                .. "/h",
            inline = true,
        }

        fields[#fields + 1] = {
            name = "⭐ Session EXP",
            value = session.formatWebhookNumber(summary.exp)
                .. "\n≈ "
                .. session.formatWebhookNumber(summary.expPerHour)
                .. "/h",
            inline = true,
        }
        fields[#fields + 1] = {
            name = "⏱ Session Runtime",
            value = session.formatWebhookDuration(summary.runtime)
                .. "\nAvg run: "
                .. session.formatWebhookDuration(summary.avgRunSeconds),
            inline = true,
        }
    end

    if not isTest
        and Toggles.CTDIGWebhookRewards
        and Toggles.CTDIGWebhookRewards.Value == true
    then
        fields[#fields + 1] = {
            name = "Other Rewards",
            value = session.getWebhookRewards(),
            inline = false,
        }
    end

    local mention = Options.CTDIGWebhookMention
        and tostring(Options.CTDIGWebhookMention.Value or "") or ""
    mention = mention:match("(%d+)") or ""

    local payload = {
        username = "CTDIG",
        content = mention ~= "" and ("<@" .. mention .. ">") or nil,
        allowed_mentions = {
            parse = {},
            users = mention ~= "" and { mention } or {},
        },
        embeds = {
            {
                title = title,
                color = color,
                fields = fields,
                footer = {
                    text = "CTDIG • " .. tostring(session.replayBuild or "Webhook"),
                },
                timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
            },
        },
    }

    local okEncode, body = pcall(function()
        return game:GetService("HttpService"):JSONEncode(payload)
    end)

    if not okEncode then
        session.webhook.busy = false
        session.setWebhookStatus("Webhook: JSON error")
        return false, tostring(body)
    end

    local okRequest, response = pcall(function()
        return requestFn({
            Url = url,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
            },
            Body = body,
        })
    end)

    session.webhook.busy = false

    if not okRequest then
        session.setWebhookStatus("Webhook: request error")
        return false, tostring(response)
    end

    local statusCode
    if type(response) == "table" then
        statusCode = tonumber(response.StatusCode or response.Status or response.status_code)
        if response.Success == false then
            session.setWebhookStatus("Webhook: HTTP " .. tostring(statusCode or "failed"))
            return false, "request returned failure"
        end
    end

    if statusCode and (statusCode < 200 or statusCode >= 300) then
        session.setWebhookStatus("Webhook: HTTP " .. tostring(statusCode))
        return false, "HTTP " .. tostring(statusCode)
    end

    session.setWebhookStatus(
        isTest
            and "Webhook: test sent"
            or ("Webhook: " .. cleanResult .. " sent")
    )

    pcall(function()
        notify(
            "Webhook",
            isTest and "Test message sent" or (cleanResult .. " sent"),
            3
        )
    end)

    return true
end

function session.observeWebhookResult(endFrame, result)
    local state = session.webhook
    local enabled = Toggles.CTDIGWebhookEnabled
        and Toggles.CTDIGWebhookEnabled.Value == true

    if not endFrame or (result ~= "Triumph" and result ~= "Defeat") then
        if state.endActive then
            state.endActive = false
            state.endResult = nil
            state.endSeenAt = 0
            state.sent = false
            state.busy = false
            state.attempts = 0
            state.nextAttempt = 0
            state.accounted = false
        end

        if enabled then
            session.setWebhookStatus("Webhook: waiting for result")
        else
            session.setWebhookStatus("Webhook: disabled")
        end
        return
    end

    if not state.accounted then
        session.accountWebhookRun(result)
        state.accounted = true
    end

    if not enabled then
        session.setWebhookStatus("Webhook: disabled")
        return
    end

    local wantsResult =
        (result == "Triumph"
            and Toggles.CTDIGWebhookVictory
            and Toggles.CTDIGWebhookVictory.Value == true)
        or
        (result == "Defeat"
            and Toggles.CTDIGWebhookDefeat
            and Toggles.CTDIGWebhookDefeat.Value == true)

    if not wantsResult then
        session.setWebhookStatus("Webhook: " .. result .. " ignored")
        return
    end

    local now = os.clock()

    if not state.endActive or state.endResult ~= result then
        state.endActive = true
        state.endResult = result
        state.endSeenAt = now
        state.sent = false
        state.busy = false
        state.attempts = 0
        state.nextAttempt = now + 0.8
    end

    if state.sent or state.busy or now < (state.nextAttempt or 0) then
        return
    end

    state.attempts = (state.attempts or 0) + 1

    local ok, err = session.sendWebhook(result, false)
    if ok then
        state.sent = true
        return
    end

    if state.attempts >= 3 then
        state.sent = true
        session.setWebhookStatus(
            "Webhook: failed after 3 attempts | " .. tostring(err)
        )
        return
    end

    state.nextAttempt = os.clock() + 2
    session.setWebhookStatus(
        "Webhook: retry " .. tostring(state.attempts + 1) .. "/3"
    )
end

function session.getDeckSnapshot()
    local data = player:FindFirstChild("PlayerData")
    local loadout = data and data:FindFirstChild("Loadout")
    if not loadout then
        return {}
    end

    local slots = {}
    for _, child in ipairs(loadout:GetChildren()) do
        if child:IsA("ValueBase") then
            local index = tonumber(child.Name:match("^Tower(%d+)$"))
            if index then
                slots[#slots + 1] = { index = index, value = tostring(child.Value) }
            end
        end
    end

    table.sort(slots, function(a, b)
        return a.index < b.index
    end)

    local deck = {}
    for _, slot in ipairs(slots) do
        deck[#deck + 1] = slot.value
    end
    return deck
end

function session.compactDeckText(deck)
    local out = {}
    for _, name in ipairs(deck or {}) do
        if name and name ~= "" and name ~= "None" then
            out[#out + 1] = tostring(name)
        end
    end
    return #out > 0 and table.concat(out, ", ") or "empty"
end

local function getTowers()
    return Workspace:FindFirstChild("Towers")
end

local function getGameVals()
    return Workspace:FindFirstChild("GameVals")
end

local function getNativeAutoSkipSetting()
    local data = player:FindFirstChild("PlayerData")
    local settings = data and data:FindFirstChild("Settings")
    return settings and settings:FindFirstChild("AutoSkip")
end

local function getSettingsRemote()
    local buttons = playerGui:FindFirstChild("Buttons")
    local settingsFrame = buttons and buttons:FindFirstChild("SettingsFrame")
    local mainFrame = settingsFrame and settingsFrame:FindFirstChild("MainFrame")
    local controller = mainFrame and mainFrame:FindFirstChild("LocalScript")
    local remote = controller and controller:FindFirstChild("RemoteEvent")

    if remote and remote:IsA("RemoteEvent") then
        return remote
    end

    if mainFrame then
        for _, object in ipairs(mainFrame:GetDescendants()) do
            if object:IsA("RemoteEvent") and object.Parent and object.Parent:IsA("LocalScript") then
                return object
            end
        end
    end
end

local function setNativeAutoSkip(enabled)
    enabled = enabled == true
    local setting = getNativeAutoSkipSetting()
    if not setting then
        return false, "PlayerData.Settings.AutoSkip is missing"
    end

    if setting.Value == enabled then
        return true
    end

    local remote = getSettingsRemote()
    if not remote then
        return false, "native settings RemoteEvent is missing"
    end

    local ok, err = pcall(function()
        remote:FireServer("AutoSkip")
    end)
    if not ok then
        return false, tostring(err)
    end

    local started = os.clock()
    while session.alive and os.clock() - started < 2 do
        if setting.Value == enabled then
            return true
        end
        task.wait(0.05)
    end

    return setting.Value == enabled, "server did not change AutoSkip"
end

local function getDetects()
    local service = Workspace:FindFirstChild("WorkspaceScriptService")
    local storage = service and service:FindFirstChild("DetectStorage")
    return storage and storage:FindFirstChild("EverythingDetects")
end

local function getOwner(tower)
    local config = tower and tower:FindFirstChild("Configuration")
    local owner = config and config:FindFirstChild("Owner")

    if owner then
        if typeof(owner.Value) == "Instance" then
            return owner.Value.Name
        end
        return tostring(owner.Value)
    end

    local attribute = tower and tower:GetAttribute("Owner")
    return attribute and tostring(attribute) or nil
end

local function isMine(tower)
    return tower and tower.Parent and getOwner(tower) == player.Name
end

local function getLevel(tower)
    local config = tower and tower:FindFirstChild("Configuration")
    local level = config and config:FindFirstChild("Level")
    return level and tonumber(level.Value) or 0
end

local function getTarget(tower)
    if not tower then
        return nil
    end

    -- game2 keeps OtherConfig inside Configuration, not at tower root.
    -- Keep the root fallback only for compatibility with unusual/special towers.
    local config = tower:FindFirstChild("Configuration")
    local other = config and config:FindFirstChild("OtherConfig")
        or tower:FindFirstChild("OtherConfig")
    local targets = other and other:FindFirstChild("Targets")
    return targets and tostring(targets.Value) or nil
end

local function getRoot(object)
    if not object then
        return nil
    end

    if object:IsA("BasePart") then
        return object
    end

    -- Runtime tower/enemy containers are not guaranteed to be Models.
    -- Some game objects are Folders that directly own HumanoidRootPart and
    -- replicated Configuration/health values.  Never discard them by class.
    if object:IsA("Model") and object.PrimaryPart then
        return object.PrimaryPart
    end

    local named = object:FindFirstChild("HumanoidRootPart", true)
        or object:FindFirstChild("RootPart", true)
        or object:FindFirstChild("Torso", true)
    if named and named:IsA("BasePart") then
        return named
    end

    return object:FindFirstChildWhichIsA("BasePart", true)
end

local function vec(v)
    return {
        x = math.round(v.X * 1000) / 1000,
        y = math.round(v.Y * 1000) / 1000,
        z = math.round(v.Z * 1000) / 1000,
    }
end

local function toVector3(v)
    if type(v) ~= "table" then
        return Vector3.zero
    end
    return Vector3.new(tonumber(v.x) or 0, tonumber(v.y) or 0, tonumber(v.z) or 0)
end

local function pathUnder(root, object)
    if not root or not object or object == root or not object:IsDescendantOf(root) then
        return nil
    end

    local path = {}
    local current = object

    while current and current ~= root do
        local parent = current.Parent
        if not parent then
            return nil
        end

        local index = 0
        for _, sibling in ipairs(parent:GetChildren()) do
            if sibling.Name == current.Name and sibling.ClassName == current.ClassName then
                index = index + 1
                if sibling == current then
                    break
                end
            end
        end

        table.insert(path, 1, {
            name = current.Name,
            class = current.ClassName,
            index = index,
        })
        current = parent
    end

    return path
end

local function resolvePath(root, path)
    if not root or type(path) ~= "table" then
        return nil
    end

    local current = root
    for _, step in ipairs(path) do
        if type(step) == "string" then
            current = current and current:FindFirstChild(step)
        elseif type(step) == "table" and current then
            local wantedIndex = tonumber(step.index) or 1
            local foundIndex = 0
            local found

            for _, child in ipairs(current:GetChildren()) do
                if child.Name == step.name and (not step.class or child.ClassName == step.class) then
                    foundIndex = foundIndex + 1
                    if foundIndex == wantedIndex then
                        found = child
                        break
                    end
                end
            end

            current = found
        else
            current = nil
        end

        if not current then
            return nil
        end
    end

    return current
end

local function sourceFor(object)
    if typeof(object) ~= "Instance" then
        return nil
    end

    if object:IsDescendantOf(playerGui) then
        return { root = "PlayerGui", path = pathUnder(playerGui, object) }
    end

    if object:IsDescendantOf(player) then
        return { root = "Player", path = pathUnder(player, object) }
    end

    if object:IsDescendantOf(ReplicatedStorage) then
        return { root = "ReplicatedStorage", path = pathUnder(ReplicatedStorage, object) }
    end
end

local function resolveSource(source)
    if type(source) ~= "table" then
        return nil
    end

    local root
    if source.root == "PlayerGui" then
        root = playerGui
    elseif source.root == "Player" then
        root = player
    elseif source.root == "ReplicatedStorage" then
        root = ReplicatedStorage
    end

    return resolvePath(root, source.path)
end

local function getCTDModule()
    if ctdModule ~= nil then
        return ctdModule or nil

    end

    local modules = ReplicatedStorage:FindFirstChild("Modules")
    local moduleScript = modules and modules:FindFirstChild("CTDModule")
    if not moduleScript then
        ctdModule = false
        return nil
    end

    local ok, module = pcall(require, moduleScript)
    if not ok then
        warn("[CTDIG] CTDModule require failed: " .. tostring(module))
    end
    ctdModule = ok and module or false
    return ctdModule or nil
end

do
local function readNumberValue(root, name, recursive)
    if not root then
        return nil
    end

    local value = root:FindFirstChild(name, recursive == true)
    if value and value:IsA("ValueBase") then
        return tonumber(value.Value)
    end
end

local function formatCompactNumber(value)
    value = tonumber(value) or 0
    local abs = math.abs(value)

    if abs >= 1000000000 then
        return string.format("%.1fB", value / 1000000000)
    elseif abs >= 1000000 then
        return string.format("%.1fM", value / 1000000)
    elseif abs >= 1000 then
        return string.format("%.1fK", value / 1000)
    elseif abs >= 100 then
        return string.format("%.0f", value)
    elseif abs >= 10 then
        return string.format("%.1f", value)
    end

    return string.format("%.2f", value)
end

local function setRangeInfo(text)
    pcall(function()
        if rangeInfoLabel and type(rangeInfoLabel.SetText) == "function" then
            rangeInfoLabel:SetText(text)
        elseif Options.CTDIGRangeInfo and type(Options.CTDIGRangeInfo.SetText) == "function" then
            Options.CTDIGRangeInfo:SetText(text)
        end
    end)
end

local function unitLevelRanges(unitName, preview, surface)
    local units = ReplicatedStorage:FindFirstChild("Units")
    local unitFolder = units and units:FindFirstChild(unitName)
    local levels = unitFolder and unitFolder:FindFirstChild("Levels")
    if not levels then
        return {}
    end

    local module = getCTDModule()
    local entries = {}

    for _, levelFolder in ipairs(levels:GetChildren()) do
        local level = tonumber(levelFolder.Name)
        if level ~= nil then
            local settings = levelFolder:FindFirstChild("Settings")
            local range = readNumberValue(settings, "Range")
            local range2 = readNumberValue(settings, "Range2")

            if not range then
                local objects = levelFolder:FindFirstChild("Object")
                local object = objects and (objects:FindFirstChild(unitName)
                    or objects:FindFirstChildWhichIsA("Model")
                    or objects:FindFirstChildWhichIsA("BasePart"))
                local config = object and object:FindFirstChild("Configuration")
                range = readNumberValue(config, "Range") or readNumberValue(object, "Range", true)
                range2 = range2 or readNumberValue(config, "Range2")
            end

            if range and range > 0 then
                -- Re-run exactly the game's perk/map/surface modifier pass on a
                -- tiny local stat container. dochecktowermodifications only needs
                -- Name + Configuration for Range/Range2 and the placed surface.
                if module and type(module.dochecktowermodifications) == "function" then
                    local fake = Instance.new("Folder")
                    fake.Name = unitName
                    local fakeConfig = Instance.new("Folder")
                    fakeConfig.Name = "Configuration"
                    fakeConfig.Parent = fake

                    local rv = Instance.new("NumberValue")
                    rv.Name = "Range"
                    rv.Value = range
                    rv.Parent = fakeConfig

                    if range2 and range2 > 0 then
                        local rv2 = Instance.new("NumberValue")
                        rv2.Name = "Range2"
                        rv2.Value = range2
                        rv2.Parent = fakeConfig
                    end

                    local ok = pcall(module.dochecktowermodifications, player, fake, {
                        ManualPlacedOnPart = surface,
                    })
                    if ok then
                        range = readNumberValue(fakeConfig, "Range") or range
                        range2 = readNumberValue(fakeConfig, "Range2") or range2
                    end
                    fake:Destroy()
                end

                entries[#entries + 1] = {
                    sourceLevel = level,
                    range = range,
                    range2 = range2 and range2 > 0 and range2 or nil,
                }
            end
        end
    end

    table.sort(entries, function(a, b)
        return a.sourceLevel < b.sourceLevel
    end)

    while #entries > 8 do
        table.remove(entries)
    end

    return entries
end

