do
    local source = [===[-- XOMA AutoExec patch
-- Build: PASS7-AUTOEXEC-V17
-- Loaded after the V16 core so old Recorder/XOMA syntax stays compatible.

local environment = typeof(getgenv) == "function" and getgenv() or _G
local session = environment.CTDIG_SESSION

if type(session) ~= "table"
    or type(session.auto) ~= "table"
    or type(session.XOMA) ~= "table"
then
    error("XOMA V17 patch: CTDIG session is unavailable")
end

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local StarterGui = game:GetService("StarterGui")

local player = Players.LocalPlayer
local remotes = ReplicatedStorage:WaitForChild("Remotes", 20)

local function status(text)
    print("[XOMA AutoExec] " .. tostring(text))
end

local function notify(title, text, duration)
    pcall(function()
        StarterGui:SetCore("SendNotification", {
            Title = tostring(title),
            Text = tostring(text or ""),
            Duration = duration or 4,
        })
    end)
end

local function tracebackError(err)
    if debug and type(debug.traceback) == "function" then
        return debug.traceback(tostring(err), 2)
    end
    return tostring(err)
end

local function getMapName()
    local map = Workspace:FindFirstChild("Map")
    local trueName = map and map:FindFirstChild("TrueName")
    return trueName and tostring(trueName.Value)
        or (map and map.Name or "Unknown")
end

local function getCTDModule()
    local modules = ReplicatedStorage:FindFirstChild("Modules")
    local moduleScript = modules and modules:FindFirstChild("CTDModule")
    if not moduleScript then
        return nil
    end

    local ok, module = pcall(require, moduleScript)
    return ok and module or nil
end

session.combatBuild = "PASS7-AUTOEXEC-V17"
session.replayBuild = "PASS7-AUTOEXEC-V17"
session.autoBuild = "PASS7-AUTOEXEC-V17"

function session.auto.normalizeDeck(deck)
    local normalized = {}

    for _, unitName in ipairs(type(deck) == "table" and deck or {}) do
        unitName = tostring(unitName or "")
        if unitName ~= "" and unitName ~= "None" then
            normalized[#normalized + 1] = unitName
        end
    end

    return normalized
end

function session.auto.deckExactMatches(a, b)
    a = session.auto.normalizeDeck(a)
    b = session.auto.normalizeDeck(b)

    if #a ~= #b then
        return false
    end

    for i = 1, #a do
        if a[i] ~= b[i] then
            return false
        end
    end

    return true
end

function session.auto.loadoutDataDeck(data)
    local towers = type(data) == "table" and data.Towers or nil
    if type(towers) ~= "table" then
        return {}
    end

    local slots = {}
    for key, value in pairs(towers) do
        local index = tonumber(tostring(key):match("^Tower(%d+)$"))
        if index then
            slots[#slots + 1] = {
                index = index,
                value = tostring(value),
            }
        end
    end

    table.sort(slots, function(a, b)
        return a.index < b.index
    end)

    local deck = {}
    for _, slot in ipairs(slots) do
        deck[#deck + 1] = slot.value
    end

    return session.auto.normalizeDeck(deck)
end

function session.auto.verifyCurrentMacroDeck(macro)
    local required = session.auto.requiredUnitsFromMacro(macro)
    local wanted = session.auto.normalizeDeck(
        type(macro) == "table" and macro.deck or nil
    )
    local current = session.auto.normalizeDeck(session.getDeckSnapshot())

    if #wanted > 0 then
        if session.auto.deckExactMatches(current, wanted) then
            return true
        end

        return false, "expected: "
            .. session.compactDeckText(wanted)
            .. " | current: "
            .. session.compactDeckText(current)
    end

    if #required == 0 then
        return true
    end

    if #current == 0 then
        return false, "PlayerData.Loadout is empty/unavailable"
    end

    local ok, missing = session.auto.deckContainsRequired(current, required)
    if ok then
        return true
    end

    return false, "missing "
        .. tostring(missing)
        .. " | current: "
        .. session.compactDeckText(current)
end

function session.auto.ensureMacroDeckInLobby(macro)
    local required = session.auto.requiredUnitsFromMacro(macro)
    local wantedDeck = session.auto.normalizeDeck(
        type(macro) == "table" and macro.deck or nil
    )

    if #required == 0 and #wantedDeck == 0 then
        return true
    end

    local data = player:WaitForChild("PlayerData", 20)
    local loadout = data and data:WaitForChild("Loadout", 20)
    if not loadout then
        return false, "PlayerData.Loadout was not found"
    end

    local current = session.auto.normalizeDeck(session.getDeckSnapshot())
    if #wantedDeck > 0 then
        if session.auto.deckExactMatches(current, wantedDeck) then
            return true
        end
    else
        local contains = session.auto.deckContainsRequired(current, required)
        if contains then
            return true
        end
    end

    local module = getCTDModule()
    if not module or type(module.PlayerLoadouts) ~= "function" then
        return false, "CTDModule.PlayerLoadouts is unavailable"
    end

    if type(module.waitforload) == "function" then
        pcall(module.waitforload)
    end

    local ok, loadouts = pcall(module.PlayerLoadouts, player, "GetLoadouts")
    if not ok or type(loadouts) ~= "table" then
        return false, "GetLoadouts failed: " .. tostring(loadouts)
    end

    local selectedCode
    local selectedDeck

    for code, loadoutData in pairs(loadouts) do
        local deck = session.auto.loadoutDataDeck(loadoutData)
        local valid = false

        if #wantedDeck > 0 then
            valid = session.auto.deckExactMatches(deck, wantedDeck)
        else
            valid = session.auto.deckContainsRequired(deck, required) == true
        end

        if valid then
            selectedCode = code
            selectedDeck = deck
            break
        end
    end

    if selectedCode == nil then
        if #wantedDeck > 0 then
            return false, "no saved loadout exactly matches: "
                .. session.compactDeckText(wantedDeck)
        end

        return false, "no saved loadout contains: "
            .. table.concat(required, ", ")
    end

    status(
        "equipping "
            .. tostring(selectedCode)
            .. " | "
            .. session.compactDeckText(selectedDeck)
    )

    local equipOk, equipResult = pcall(
        module.PlayerLoadouts,
        player,
        "EquipLoadout",
        {
            loadoutcode = tostring(selectedCode),
        }
    )

    if not equipOk then
        return false, "EquipLoadout failed: " .. tostring(equipResult)
    end

    local started = os.clock()
    while session.alive and os.clock() - started < 10 do
        local deck = session.auto.normalizeDeck(session.getDeckSnapshot())
        local ready

        if #wantedDeck > 0 then
            ready = session.auto.deckExactMatches(deck, wantedDeck)
        else
            ready = session.auto.deckContainsRequired(deck, required) == true
        end

        if ready then
            notify(
                "AutoExecute",
                "Deck equipped: " .. session.compactDeckText(deck),
                3
            )
            return true
        end

        task.wait(0.1)
    end

    return false, "deck did not update after EquipLoadout | current: "
        .. session.compactDeckText(session.getDeckSnapshot())
end

function session.auto.isElevatorRoomCandidate(object)
    if not object
        or not (object:IsA("Folder") or object:IsA("Model"))
    then
        return false
    end

    return object:FindFirstChild("CurrentMap") ~= nil
        and object:FindFirstChild("RoomOwner") ~= nil
        and object:FindFirstChild("RoomOpen") ~= nil
        and object:FindFirstChild("RoomEntryMode") ~= nil
        and object:FindFirstChild("Limit") ~= nil
        and object:FindFirstChild("MapMode") ~= nil
        and object:FindFirstChild("CurrentPlayers") ~= nil
        and object:FindFirstChild("baseplate", true) ~= nil
end

function session.auto.collectElevatorRooms()
    local root = Workspace:FindFirstChild("Elevators")
    local rooms = {}
    if not root then
        return rooms
    end

    for _, group in ipairs(root:GetChildren()) do
        if group.Name ~= "ClassicElevators" then
            for _, object in ipairs(group:GetDescendants()) do
                if session.auto.isElevatorRoomCandidate(object) then
                    rooms[#rooms + 1] = object
                end
            end
        end
    end

    table.sort(rooms, function(a, b)
        local ao = a:FindFirstChild("RoomOwner")
        local bo = b:FindFirstChild("RoomOwner")
        local ar = a:FindFirstChild("RoomOpen")
        local br = b:FindFirstChild("RoomOpen")

        local aOwned = ao and tostring(ao.Value) == player.Name
        local bOwned = bo and tostring(bo.Value) == player.Name
        if aOwned ~= bOwned then
            return aOwned
        end

        local aFree = (not ao or tostring(ao.Value) == "")
            and (not ar or ar.Value == false)
        local bFree = (not bo or tostring(bo.Value) == "")
            and (not br or br.Value == false)

        if aFree ~= bFree then
            return aFree
        end

        return a:GetFullName() < b:GetFullName()
    end)

    return rooms
end

function session.auto.moveIntoElevator(room)
    local character = player.Character or player.CharacterAdded:Wait()
    local root = character:FindFirstChild("HumanoidRootPart")
        or character:FindFirstChild("Torso")
        or character.PrimaryPart
    local plate = room and room:FindFirstChild("baseplate", true)

    if not root or not plate or not plate:IsA("BasePart") then
        return false, "elevator root/baseplate missing"
    end

    local owner = room:FindFirstChild("RoomOwner")
    local roomOpen = room:FindFirstChild("RoomOpen")

    if owner
        and tostring(owner.Value) ~= ""
        and tostring(owner.Value) ~= player.Name
    then
        return false, "elevator is owned by " .. tostring(owner.Value)
    end

    if roomOpen
        and roomOpen.Value == true
        and (not owner or tostring(owner.Value) ~= player.Name)
    then
        return false, "elevator is already open"
    end

    for attempt = 1, 3 do
        if not session.alive then
            return false, "stopped"
        end

        root.CFrame = plate.CFrame * CFrame.new(0, 3, 0)

        if typeof(firetouchinterest) == "function" then
            pcall(function()
                firetouchinterest(root, plate, 0)
                task.wait(0.05)
                firetouchinterest(root, plate, 1)
            end)
        end

        local started = os.clock()
        while session.alive and os.clock() - started < 2.25 do
            if session.auto.playerInsideElevator(room) then
                return true
            end

            if owner
                and tostring(owner.Value) ~= ""
                and tostring(owner.Value) ~= player.Name
            then
                break
            end

            task.wait(0.08)
        end

        status("enter elevator retry " .. tostring(attempt + 1))
    end

    -- The native lobby can call EnterElevator on the client before RoomOwner /
    -- CurrentPlayers visibly replicate. OpenRoom is the authoritative check.
    if not owner
        or tostring(owner.Value) == ""
        or tostring(owner.Value) == player.Name
    then
        return true
    end

    return false, "EnterElevator was not confirmed"
end

function session.auto.openMacroMapFromLobby(macro)
    local elevators = remotes:FindFirstChild("Elevators")
    if not elevators or not elevators:IsA("RemoteFunction") then
        return false, "Remotes.Elevators is missing"
    end

    if type(macro.map) ~= "string"
        or macro.map == ""
        or macro.map == "Unknown"
    then
        return false, "macro has no valid map name"
    end

    local deadline = os.clock() + 35
    local lastError = "no free elevator accepted OpenRoom"

    while session.alive and os.clock() < deadline do
        local rooms = session.auto.collectElevatorRooms()

        if #rooms == 0 then
            lastError = "no room-system elevators were found"
            status("waiting for elevator rooms")
            task.wait(0.5)
        else
            for index, room in ipairs(rooms) do
                if not session.alive then
                    return false, "stopped"
                end

                local owner = room:FindFirstChild("RoomOwner")
                local roomOpen = room:FindFirstChild("RoomOpen")
                local ownerText = owner and tostring(owner.Value) or ""

                local usable = ownerText == player.Name
                    or (
                        ownerText == ""
                        and (not roomOpen or roomOpen.Value == false)
                    )

                if usable then
                    status(
                        string.format(
                            "elevator %d/%d | entering",
                            index,
                            #rooms
                        )
                    )

                    local moved, moveError =
                        session.auto.moveIntoElevator(room)

                    if moved then
                        local currentMap = room:FindFirstChild("CurrentMap")
                        local limit = room:FindFirstChild("Limit")
                        local entry = room:FindFirstChild("RoomEntryMode")
                        local mapMode = room:FindFirstChild("MapMode")

                        pcall(function()
                            currentMap.Value = macro.map
                        end)
                        pcall(function()
                            limit.Value = 1
                        end)
                        pcall(function()
                            entry.Value = "FriendsOnly"
                        end)
                        pcall(function()
                            mapMode.Value = "Classic"
                        end)

                        local payload = {
                            Gamemode = "Classic",
                            CurrentMap = macro.map,
                            Limit = 1,
                            RoomEntryMode = "FriendsOnly",
                            MapMode = "Classic",
                            MapModifiers = {},
                        }

                        status(
                            "opening "
                                .. macro.map
                                .. " | FriendsOnly | Limit 1"
                        )

                        local callOk, opened = pcall(function()
                            return elevators:InvokeServer(
                                room,
                                "OpenRoom",
                                payload
                            )
                        end)

                        if callOk and opened == true then
                            local confirmed = false
                            local confirmStarted = os.clock()

                            while session.alive
                                and os.clock() - confirmStarted < 3
                            do
                                local replicatedOwner =
                                    owner and tostring(owner.Value) or ""
                                local replicatedMap =
                                    currentMap and tostring(currentMap.Value) or ""
                                local replicatedEntry =
                                    entry and tostring(entry.Value) or ""
                                local replicatedOpen =
                                    roomOpen and roomOpen.Value == true or false

                                if replicatedOwner == player.Name
                                    and replicatedMap == macro.map
                                    and replicatedEntry == "FriendsOnly"
                                    and replicatedOpen
                                then
                                    confirmed = true
                                    break
                                end

                                task.wait(0.08)
                            end

                            if confirmed then
                                status("room replication confirmed")
                            else
                                -- OpenRoom returned true; the native lobby treats
                                -- that as success, so do not reject a slow replica.
                                status("OpenRoom accepted | waiting teleport")
                            end

                            notify(
                                "AutoExecute",
                                "Room ready: "
                                    .. macro.map
                                    .. " | FriendsOnly",
                                3
                            )

                            for teleportAttempt = 1, 3 do
                                if not session.alive then
                                    return false, "stopped"
                                end

                                status(
                                    string.format(
                                        "teleport %d/3 | %s",
                                        teleportAttempt,
                                        macro.map
                                    )
                                )

                                local tpOk, tpResult = pcall(function()
                                    return elevators:InvokeServer(
                                        room,
                                        "Teleport"
                                    )
                                end)

                                if tpOk and tpResult ~= false then
                                    notify(
                                        "AutoExecute",
                                        "Teleport requested: " .. macro.map,
                                        4
                                    )
                                    return true
                                end

                                lastError = tpOk
                                    and "Teleport rejected"
                                    or (
                                        "Teleport failed: "
                                        .. tostring(tpResult)
                                    )

                                task.wait(0.6)
                            end
                        else
                            lastError = callOk
                                and (
                                    "OpenRoom rejected elevator "
                                    .. tostring(index)
                                )
                                or (
                                    "OpenRoom error: "
                                    .. tostring(opened)
                                )
                        end
                    else
                        lastError = moveError or lastError
                    end
                end
            end

            status("waiting free elevator | " .. tostring(lastError))
            task.wait(0.75)
        end
    end

    return false, lastError
end

function session.auto.waitForMatchReady(macro, timeout)
    local deadline = os.clock() + (tonumber(timeout) or 35)
    local lastError = "match context not ready"

    while session.alive and os.clock() < deadline do
        local towers = Workspace:FindFirstChild("Towers")
        local map = Workspace:FindFirstChild("Map")
        local config = map and map:FindFirstChild("Configuration")
        local data = player:FindFirstChild("PlayerData")
        local loadout = data and data:FindFirstChild("Loadout")

        if towers and map and config and data and loadout then
            local currentMap = getMapName()

            if currentMap ~= "Unknown" then
                if macro.map
                    and macro.map ~= ""
                    and macro.map ~= "Unknown"
                    and currentMap ~= macro.map
                then
                    return false, "wrong map | macro: "
                        .. tostring(macro.map)
                        .. " | current: "
                        .. tostring(currentMap)
                end

                local deckOk, deckError =
                    session.auto.verifyCurrentMacroDeck(macro)

                if deckOk then
                    if not session.sourceBound then
                        session.sourceBound, session.sourceError =
                            session.recorder.bindGameSources()
                    end

                    if session.sourceBound then
                        return true
                    end

                    lastError =
                        session.sourceError or "match sources unavailable"
                else
                    lastError =
                        "waiting deck replication | " .. tostring(deckError)
                end
            else
                lastError = "waiting map TrueName"
            end
        else
            lastError = "waiting Towers/Map/PlayerData"
        end

        status(lastError)
        task.wait(0.1)
    end

    return false, lastError
end

function session.auto.runMacroInMatch(macro)
    local ready, readyError =
        session.auto.waitForMatchReady(macro, 35)

    if not ready then
        return false, readyError
    end

    status("match ready | starting replay")
    task.wait(0.15)

    local ok, replayError = xpcall(function()
        session.recorder.replayMacro(macro)
    end, tracebackError)

    if not ok then
        return false, tostring(replayError)
    end

    return true
end

function session.auto.runMacroFromCurrentPlace(macro)
    local deadline = os.clock() + 45
    local lastError = "lobby/match not detected"

    while session.alive and os.clock() < deadline do
        local lobbyContext =
            Workspace:FindFirstChild("Elevators") ~= nil
            and Workspace:FindFirstChild("Towers") == nil

        local map = Workspace:FindFirstChild("Map")
        local matchContext =
            Workspace:FindFirstChild("Towers") ~= nil
            and map ~= nil

        if lobbyContext then
            status("lobby | checking exact deck")

            local deckOk, deckError =
                session.auto.ensureMacroDeckInLobby(macro)

            if not deckOk then
                return false, "deck: " .. tostring(deckError)
            end

            status("lobby | deck OK | finding elevator")

            local roomOk, roomError =
                session.auto.openMacroMapFromLobby(macro)

            if not roomOk then
                return false, "lobby: " .. tostring(roomError)
            end

            -- The strategy file itself lives in autoexec. After Roblox
            -- teleports, the executor runs it again; XOMA:Run() sees the
            -- match place and resumes the same strategy automatically.
            return true, "teleport requested"
        end

        if matchContext then
            return session.auto.runMacroInMatch(macro)
        end

        status("waiting for lobby/match")
        task.wait(0.2)
    end

    return false, lastError
end

function session.XOMA:Run()
    local macro = self._macro

    if type(macro) ~= "table"
        or type(macro.actions) ~= "table"
    then
        error("XOMA:Run() has no valid strategy", 2)
    end

    if #macro.actions == 0 then
        error("XOMA:Run() strategy has no actions", 2)
    end

    status(
        tostring(macro.map or "Unknown")
            .. " | "
            .. tostring(#macro.actions)
            .. " actions"
    )

    local ok, result = session.auto.runMacroFromCurrentPlace(macro)
    if not ok then
        error("XOMA AutoExec error: " .. tostring(result), 2)
    end

    return true
end

return session.XOMA]===]
