                    end
                    task.wait(0.04)
                until os.clock() >= deadline
            end

            control.busy = false
        end
    end)
end

session.endClickBuild = "PASS29B-AUTORESTART-DIRECT-V40"
print("[XOMA V40] Auto Retry direct Restart watcher installed")

return session.XOMA
